// ---------------------------------------------------------------------------
// Validation Helpers (mirrors shared Zod schemas)
// ---------------------------------------------------------------------------

interface FormErrors {
  /** Field-level errors keyed by field name (empty when no field errors) */
  fields: Record<string, string>
  /** General form-level error message */
  general?: string
}

/** Validate the form data against business rules. Returns null if valid. */
function validateForm(data: CustomerFormData): FormErrors | null {
  const fields: Record<string, string> = {}

  // Type branching — required fields
  if (data.type === 'private') {
    if (!data.firstName.trim()) {
      fields.firstName = 'First name is required for private customers'
    }
    if (!data.lastName.trim()) {
      fields.lastName = 'Last name is required for private customers'
    }
  } else {
    // company
    if (!data.companyName.trim()) {
      fields.companyName = 'Company name is required for company customers'
    }
  }

  // Address conditional validation — if street is provided, number/postalCode/city must also be present
  const hasStreet = data.street.trim().length > 0
  if (hasStreet) {
    if (!data.number.trim()) {
      fields.number = 'Number is required when street is provided'
    }
    if (!data.postalCode.trim()) {
      fields.postalCode = 'Postal code is required when street is provided'
    }
    if (!data.city.trim()) {
      fields.city = 'City is required when street is provided'
    }
  }

  // Phone/email loose validation — min 1 char if provided, max 50
  if (data.phone && data.phone.length > 50) {
    fields.phone = 'Phone must be at most 50 characters'
  }
  if (data.email && data.email.length > 50) {
    fields.email = 'Email must be at most 50 characters'
  }

  return Object.keys(fields).length > 0 ? { fields } : null
}

/** Helper to create an empty errors object */
const emptyErrors: FormErrors = { fields: {} }

/** Build the API payload from form data, stripping empty strings and setting defaults */
function buildPayload(data: CustomerFormData): Record<string, unknown> {
  const payload: Record<string, unknown> = { type: data.type }

  // Always include country (defaults to BE)
  if (data.country.trim()) {
    payload.country = data.country.trim()
  } else {
    payload.country = 'BE'
  }

  // Type-branching fields — only include relevant ones
  if (data.type === 'private') {
    if (data.firstName.trim()) payload.firstName = data.firstName.trim()
    if (data.lastName.trim()) payload.lastName = data.lastName.trim()
  } else {
    if (data.companyName.trim()) payload.companyName = data.companyName.trim()
  }

  // Optional fields — only include non-empty values
  if (data.vatId.trim()) payload.vatId = data.vatId.trim()
  if (data.phone.trim()) payload.phone = data.phone.trim()
  if (data.email.trim()) payload.email = data.email.trim()

  // Address fields — only include non-empty values
  if (data.street.trim()) payload.street = data.street.trim()
  if (data.number.trim()) payload.number = data.number.trim()
  if (data.bus.trim()) payload.bus = data.bus.trim()
  if (data.postalCode.trim()) payload.postalCode = data.postalCode.trim()
  if (data.city.trim()) payload.city = data.city.trim()

  return payload
}

