// ---------------------------------------------------------------------------
// Main Dialog Component
// ---------------------------------------------------------------------------

interface CustomerFormDialogProps {
  /** Whether the dialog is open */
  open: boolean
  /** Callback when dialog opens/closes */
  onOpenChange: (open: boolean) => void
  /** Existing customer for edit mode; null for create mode */
  editingCustomer?: CustomerDetail | null
  /** Called after successful save — typically to refresh the list */
  onSaveSuccess: () => void
}

export function CustomerFormDialog({
  open,
  onOpenChange,
  editingCustomer,
  onSaveSuccess,
}: CustomerFormDialogProps) {
  const isEditMode = editingCustomer != null

  // Form state — resets when dialog opens/closes or mode changes
  const [formData, setFormData] = useState<CustomerFormData>(createEmptyForm)
  const [errors, setErrors] = useState<FormErrors | null>(null)
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Address search state — separate from formData to power comboboxes.
  const [postalCodeResult, setPostalCodeResult] = useState<PostalCodeResult | null>(null)
  const [streetResult, setStreetResult] = useState<StreetResult | null>(null)

  // Reset form when dialog opens or customer changes
  useEffect(() => {
    if (open) {
      const newForm = editingCustomer ? populateForm(editingCustomer) : createEmptyForm()
      setFormData(newForm)

      // In edit mode, reconstruct postal code and street result objects so the
      // comboboxes display their saved values instead of showing empty.
      if (editingCustomer && newForm.postalCode) {
        setPostalCodeResult({
          code: newForm.postalCode,
          name: newForm.postalCode, // Display only the code
          municipality: newForm.city ?? '',
        })
      } else {
        setPostalCodeResult(null)
      }

      // Reconstruct street result if customer has a saved address — displays it
      // as readonly with a clear button, allowing users to search for a new one.
      if (editingCustomer && newForm.street) {
        setStreetResult({
          name: newForm.street,
          postalCode: newForm.postalCode ?? '',
          municipality: newForm.city ?? '',
        })
      } else {
        setStreetResult(null)
      }

      setErrors(null)
      setIsSubmitting(false)
    }
  }, [open, editingCustomer])

  // -----------------------------------------------------------------------
  // Field change handler
  // -----------------------------------------------------------------------

  const handleFieldChange = useCallback((name: string, value: string) => {
    setFormData((prev) => ({ ...prev, [name]: value }))
    // Clear field error when user starts typing
    if (errors && errors.fields[name]) {
      setErrors({ ...errors, fields: { ...errors.fields, [name]: '' } })
    }
  }, [errors])

  // -----------------------------------------------------------------------
  // Type change handler — resets type-specific fields on switch
  // -----------------------------------------------------------------------

  const handleTypeChange = useCallback((type: 'private' | 'company') => {
    setFormData((prev) => ({ ...prev, type }))
    // Clear type-specific errors when switching
    if (errors && (errors.fields.firstName || errors.fields.lastName || errors.fields.companyName)) {
      setErrors({
        ...errors,
        fields: {
          ...errors.fields,
          firstName: '',
          lastName: '',
          companyName: '',
        },
      })
    }
  }, [errors])

  // -----------------------------------------------------------------------
  // Country change handler — handles free text fallback
  // -----------------------------------------------------------------------

  const handleCountryChange = useCallback((value: string) => {
    if (value === '__custom__') {
      setFormData((prev) => ({ ...prev, country: '' }))
    } else {
      setFormData((prev) => ({ ...prev, country: value }))
    }
  }, [])

  // -----------------------------------------------------------------------
  // Postal code selection handler
  // -----------------------------------------------------------------------

  const handlePostalCodeSelect = useCallback(
    (result: PostalCodeResult | null) => {
      if (result) {
        // Set display name to code only (city is handled by separate field).
        setPostalCodeResult({ ...result, name: result.code })
        setFormData((prev) => ({
          ...prev,
          postalCode: result.code,
          city: result.municipality, // auto-fill from postal code
        }))
        // Street becomes valid for the new postal code — clear previous selection.
        setStreetResult(null)
      } else {
        setPostalCodeResult(null)
        setFormData((prev) => ({
          ...prev,
          postalCode: '',
          city: prev.city ? '' : prev.city, // only clear if still auto-filled
        }))
        // Clear street too since it was scoped to the old postal code.
        setStreetResult(null)
      }
    },
    [],
  )

  // -----------------------------------------------------------------------
  // Street selection handler
  // -----------------------------------------------------------------------

  const handleStreetSelect = useCallback((result: StreetResult | null) => {
    if (result) {
      setStreetResult(result)
      setFormData((prev) => ({ ...prev, street: result.name }))
    } else {
      setStreetResult(null)
      setFormData((prev) => ({ ...prev, street: '' }))
    }
  }, [])

  // -----------------------------------------------------------------------
  // City reset handler — clears auto-fill and allows free text editing.
  // -----------------------------------------------------------------------

  const handleCityReset = useCallback(() => {
    setFormData((prev) => ({ ...prev, city: '' }))
  }, [])

  // -----------------------------------------------------------------------
  // Submit handler
  // -----------------------------------------------------------------------

  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault()

    // Validate before submission
    const validationErrors = validateForm(formData)
    if (validationErrors) {
      setErrors(validationErrors)
      return
    }

    setIsSubmitting(true)
    setErrors(emptyErrors)

    try {
      const payload = buildPayload(formData)

      if (isEditMode && editingCustomer) {
        await updateCustomer(editingCustomer.id, payload)
      } else {
        await createCustomer(payload)
      }

      onSaveSuccess()
      onOpenChange(false)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save customer'
      setErrors({ fields: {}, general: message })
    } finally {
      setIsSubmitting(false)
    }
  }, [formData, isEditMode, editingCustomer, onSaveSuccess, onOpenChange])

  // -----------------------------------------------------------------------
  // Dialog close handler — resets state
  // -----------------------------------------------------------------------

  const handleClose = useCallback(() => {
    setFormData(createEmptyForm())
    setPostalCodeResult(null)
    setStreetResult(null)
    setErrors(null)
    setIsSubmitting(false)
    onOpenChange(false)
  }, [onOpenChange])

  // -----------------------------------------------------------------------
  // Render
  // -----------------------------------------------------------------------

  return (
    <DialogPrimitive.Root open={open} onOpenChange={handleClose}>
      <DialogPrimitive.Portal>
        <DialogPrimitive.Overlay className="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <DialogPrimitive.Content
          className={cn(
            'fixed left-[50%] top-[50%] z-50 w-full max-w-lg translate-x-[-50%] translate-y-[-50%] gap-4 border bg-background p-6 shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] sm:rounded-lg',
            'max-h-[90vh] overflow-y-auto'
          )}
        >
          {/* Header */}
          <div className="flex items-center justify-between">
            <DialogPrimitive.Title className="text-lg font-semibold leading-none tracking-tight">
              {isEditMode ? 'Edit Customer' : 'New Customer'}
            </DialogPrimitive.Title>
            <DialogPrimitive.Close asChild>
              <Button variant="ghost" size="sm" className="h-6 w-6 p-0">
                <X className="h-4 w-4" />
                <span className="sr-only">Close</span>
              </Button>
            </DialogPrimitive.Close>
          </div>

          {/* General error */}
          {errors?.general && (
            <div className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
              {errors.general}
            </div>
          )}

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Type selector */}
            <fieldset className="space-y-2">
              <legend className="text-sm font-medium">Customer type</legend>
              <div className="flex gap-4">
                <label className="inline-flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="type"
                    value="private"
                    checked={formData.type === 'private'}
                    onChange={() => handleTypeChange('private')}
                    className="h-4 w-4 border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
