                    <PostalCodeCombobox
                      value={postalCodeResult}
                      onValueChange={handlePostalCodeSelect}
                      className="w-full"
                    />
                  </div>
                  {errors?.fields.postalCode && (
                    <p className="text-xs text-destructive">{errors.fields.postalCode}</p>
                  )}
                </div>

                {/* City — auto-filled from postal code, with reset button */}
                <div className="space-y-1.5">
                  <Label htmlFor="city" className={cn(formData.city && !postalCodeResult && 'text-muted-foreground')}>
                    {formData.city && !postalCodeResult ? 'City (edited)' : 'City'}
                  </Label>
                  <div className="relative h-10">
                    <Input
                      id="city"
                      name="city"
                      value={formData.city}
                      onChange={(e) => handleFieldChange('city', e.target.value)}
                      placeholder="Auto-filled from postal code"
                      className={cn(
                        'pr-7', // space for reset button
                        errors?.fields.city && 'border-destructive focus-visible:ring-destructive'
                      )}
                    />
                    {/* Reset auto-fill — only show when there's a value but no active selection */}
                    {formData.city && !postalCodeResult && (
                      <button
                        type="button"
                        onClick={handleCityReset}
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-0.5 rounded-full hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
                        tabIndex={-1}
                      >
                        <X className="h-3 w-3" />
                        <span className="sr-only">Reset auto-fill</span>
                      </button>
                    )}
                  </div>
                  {errors?.fields.city && (
                    <p className="text-xs text-destructive">{errors.fields.city}</p>
                  )}
                </div>
              </div>

              {/* Country — select with free text fallback */}
              <CountrySelect
                value={formData.country || '__custom__'}
                onChange={handleCountryChange}
                error={undefined} // country is always valid (defaults to BE)
              />
            </fieldset>

            {/* Footer actions */}
            <div className="flex justify-end gap-2 pt-2">
              <Button variant="outline" type="button" onClick={handleClose} disabled={isSubmitting}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting ? 'Saving...' : isEditMode ? 'Save changes' : 'Create customer'}
              </Button>
            </div>
          </form>
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}

